import katex from 'katex';
import { memo, useMemo } from 'react';

const cache = new Map<string, string>();

function render(tex: string, display: boolean): string {
  const key = (display ? 'D' : 'I') + tex;
  let html = cache.get(key);
  if (html === undefined) {
    html = katex.renderToString(tex, {
      displayMode: display,
      throwOnError: false,
      // only \htmlClass is used, for branch colours; all TeX is generated by this app
      trust: (ctx) => ctx.command === '\\htmlClass',
      strict: false,
      output: 'html',
    });
    if (cache.size > 2000) cache.clear();
    cache.set(key, html);
  }
  return html;
}

export const Tex = memo(function Tex({ tex, display = false, className }: { tex: string; display?: boolean; className?: string }) {
  const html = useMemo(() => render(tex, display), [tex, display]);
  return <span className={className} dangerouslySetInnerHTML={{ __html: html }} />;
});

/** Text with inline $...$ math. */
export const Rich = memo(function Rich({ text, className }: { text: string; className?: string }) {
  const parts = useMemo(() => text.split(/(\$[^$]+\$)/g).filter(Boolean), [text]);
  return (
    <span className={className}>
      {parts.map((p, i) => (p.startsWith('$') && p.endsWith('$') && p.length > 1 ? <Tex key={i} tex={p.slice(1, -1)} /> : <span key={i}>{p}</span>))}
    </span>
  );
});
